// Shared with Achille's website chat, so the app and the website behave
// alike. Generated by scripts/sync-shared.mjs: do not edit it here.

// Which language the widget's built-in strings use. The ticketing chat's
// configuration says which language it resolved for the visitor (`locale`);
// without it (Shop Assistant) the ?locale= param decides as before: none keeps
// the historical French, an unknown one falls back to English.
export function resolveUiLanguage(
  configLocale: string | null,
  urlLocale: string | null,
  supported: readonly string[]
): string {
  const fromConfig = configLocale?.slice(0, 2).toLowerCase();
  if (fromConfig && supported.includes(fromConfig)) return fromConfig;
  if (!urlLocale) return "fr";
  const lang = urlLocale.slice(0, 2).toLowerCase();
  return supported.includes(lang) ? lang : "en";
}

// A message's time. The ticketing chat formats it in the configuration's
// resolved language (fr: 17:12); without one (Shop Assistant) the browser's
// locale decides, as before.
export function formatMessageTime(dateStr: string, configLocale: string | null): string {
  const date = new Date(dateStr);
  const options: Intl.DateTimeFormatOptions = { hour: "2-digit", minute: "2-digit" };
  try {
    return date.toLocaleTimeString(configLocale ? [configLocale] : [], options);
  } catch {
    return date.toLocaleTimeString([], options);
  }
}
